referenceSolutions.javascript:
export function solve(value) {
  function walk(v) {
    if (!v) return null;
    if (Array.isArray(v)) return v.filter(Boolean).map(walk);
    if (typeof v === "object")
      return Object.fromEntries(
        Object.entries(v)
          .filter(([, x]) => Boolean(x))
          .map(([k, x]) => [k, walk(x)]),
      );
    return v;
  }
  return walk(value);
}

