type Value = any;
export function solve(value: Value): Value {
  function walk(v: Value): Value {
    if (!v) return null;
    if (Array.isArray(v)) return v.filter(Boolean).map(walk);
    if (typeof v === "object")
      return Object.fromEntries(
        Object.entries(v)
          .filter(([, x]: Value) => Boolean(x))
          .map(([k, x]: Value) => [k, walk(x)]),
      );
    return v;
  }
  return walk(value);
}
